import{_ as a,o as i,c as t,a2 as s}from"./chunks/framework.DekDpfFM.js";const k=JSON.parse('{"title":"Compilation and catalogue","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compilation.md","filePath":"guide/compilation.md","lastUpdated":1791780859000}'),o={name:"guide/compilation.md"};function n(r,e,h,l,d,c){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="compilation-and-catalogue" tabindex="-1">Compilation and catalogue <a class="header-anchor" href="#compilation-and-catalogue" aria-label="Permalink to &quot;Compilation and catalogue&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">To write</p><p>The cache, <code>LOOM_KERNELS=auto|catalogue|compile</code>, the <code>loom-kernels</code> catalogue builder, the <code>loom-toolchain</code> command, build directories, GPU architectures.</p></div><h2 id="the-catalogue-one-directory-one-tag-per-architecture" tabindex="-1">The catalogue: one directory, one tag per architecture <a class="header-anchor" href="#the-catalogue-one-directory-one-tag-per-architecture" aria-label="Permalink to &quot;The catalogue: one directory, one tag per architecture&quot;">​</a></h2><p>A catalogue is a directory, and the directory is the index:</p><pre><code>&lt;root&gt;/&lt;tag&gt;/&lt;key&gt;.so            one library per kernel
&lt;root&gt;/&lt;tag&gt;/libloom_runtime_*   the runtime they share, found next to them
&lt;root&gt;/&lt;tag&gt;/index.json          what is in it (for \`catalogue.report\`; never read to look up)
</code></pre><p>The <em>target</em> describes the architecture: the instruction-set level of a CPU (<code>x86-64-v4</code>, <code>x86-64-v3</code>, <code>x86-64-v2</code>, <code>x86-64</code>, or <code>armv8-a</code>) or the compute capability of a GPU (<code>sm_90</code> ... <code>sm_70</code>). A <em>tag</em> is <code>&lt;kind&gt;-&lt;target&gt;</code> (<code>cpu-x86-64-v3</code>, <code>cuda-sm_80</code>). The <em>key</em> of a kernel is a hash of its source: it does not depend on the architecture.</p><p><strong>Serving.</strong> A machine looks in ONE tag: the architecture its device behaves as (<code>Device.current_catalogue_tag</code>) -- a <code>stat</code>, no index to load, and only the libraries that are used get loaded. There is no fall back on a poorer architecture: its build is another code, with other results and timings. Which architecture a kernel runs as is decided by the choices table (<code>loom.kernel_parameters_for</code>, measured by <code>loom.benchmark</code>), and by nothing else. <code>LOOM_KERNELS=auto|catalogue|compile</code> says what to do when the tag has no such file.</p><p><strong>Producing.</strong> There is no tool to run: a Python script of the package that ships the catalogue runs its standard usage, and the loops on the hardware belong to it.</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loom </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> catalogue, hardware</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> catalogue.collect( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_package/_catalogue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ):</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">in</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hardware.runs():                </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># each device present, as each architecture it can behave as</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> hardware.behave_as( run ):</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">            exercise_the_package()</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">print</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">( catalogue.report( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my_package/_catalogue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ) )</span></span></code></pre></div><p>Inside <code>collect</code> the catalogue is not consulted: every kernel the program triggers is compiled, then copied under the tag of the architecture the device behaves as. Inside <code>behave_as( run )</code> the device really behaves as <code>run.target</code> (<code>LOOM_TARGET</code>): a machine can pretend to be a <em>weaker</em> one -- an AVX-512 CPU as <code>x86-64-v3</code>, a card of capability 8.9 as an 8.0 -- never a stronger one, so the program, kernels included, really runs. That is what makes it work when the hardware decides things in Python that loom does not manage (<code>device.nb_threads</code>, <code>group_size</code>): they are decided again for each architecture, and a kernel whose source depends on them gets another key. <code>catalogue.report</code> lists those kernels.</p><ul><li>A kernel is published under every architecture the program is run as.</li><li>The architectures that no hardware present can run cannot be produced (<code>hardware.uncovered</code> says which). A GPU build is made on a machine that has the card; the directories of several machines are merged.</li><li>Producing a catalogue for a wheel is done in the manylinux image (Linux) or with a <code>MACOSX_DEPLOYMENT_TARGET</code> (macOS), so that the binaries load on the oldest system supported.</li></ul><h2 id="what-a-kernel-is-made-of-body-entry-and-units" tabindex="-1">What a kernel is made of: body, entry and units <a class="header-anchor" href="#what-a-kernel-is-made-of-body-entry-and-units" aria-label="Permalink to &quot;What a kernel is made of: body, entry and units&quot;">​</a></h2><p>A kernel is not one library. For a call on the CPU or on a card, the generated source is cut in two:</p><ul><li>the <strong>body</strong> -- the work of the call and everything it instantiates -- is compiled <strong>once</strong> as a unit of its own (an <code>FfiModule</code>), and exported as a function of plain buffers (<code>loom_raw::Raw</code>), <code>int64</code> attributes and, on a card, the stream and the memory pool (<code>loom_raw::Context</code>);</li><li>the <strong>entry</strong> of each framework is a few lines that decode what the framework hands over and call the body: Jax&#39;s XLA frame (decoded by hand, <code>loom/support/ffi_raw.h</code>), or the pointer frame of Torch, Cupy and Numpy.</li></ul><p>So Jax, Torch, Cupy and Numpy share one body, and a catalogue holds it once. <code>LOOM_RAW_FFI=0</code> goes back to the typed XLA API and one library per framework.</p><p>Code that is not specific to a call is a <strong>unit</strong>: a shared library built once per (source, defines, compiler) and found beside the kernels (<code>$ORIGIN</code>). Name it with <code>FfiCode( sources = [ ... ] )</code>, either a file (<code>&quot;sdot/x.cpp&quot;</code>, with defines) or an <code>loom.FfiModule</code>:</p><div class="language-python vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">python</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">engine </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> loom.FfiModule( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;engine_3d&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">includes</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;sdot/engine/Cells.h&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ],</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">                         source</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;namespace sdot::engine </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{{</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> template LOOM_EXPORT int engine_run&lt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> local </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">{</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> seeds </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&gt;( ... ); </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">}}</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">loom.ffi_call( name, loom.FfiCode.inline( </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;...&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">sources</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> [ engine ] ), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> )</span></span></code></pre></div><p>The text is written to <code>loom_modules/&lt;name&gt;_&lt;hash&gt;.h</code> and <code>.cpp</code> (or <code>.cu</code>), compiled once, and the header is included by the kernels that name it. Entry points of a unit wear <code>LOOM_EXPORT</code>, since kernels are compiled with hidden visibility.</p><p>On a card, units are the only way to share code: the device code of a library cannot be linked to that of another one (<code>nvlink</code> links objects and static archives, not shared libraries), and a function pointer taken in one library is not callable from another. <code>kernels/cuda_support.cu</code> is such a unit: the fills that every call would otherwise instantiate for its own view types. The device flags of a catalogue build are <code>--cudart=shared</code> (the CUDA runtime of the framework is used), <code>--compress-mode=size</code>, and no PTX (a catalogue never falls back to another architecture).</p><p>The extents and byte strides of a buffer whose layout is not the identity (a card aligns its batches) cross as attributes, not as literals of the source: the same kernel serves every size.</p>`,20)])])}const u=a(o,[["render",n]]);export{k as __pageData,u as default};
